package com.gdad.bags.data.finance
import com.gdad.bags.data.local.CacheOwner
import com.gdad.bags.data.remote.*
import com.gdad.bags.domain.finance.*
import com.gdad.bags.domain.model.*
import kotlinx.coroutines.runBlocking
import org.junit.*
import org.junit.Assert.*
class ProductionFinanceRepositoryTest{@Test fun salesmanDeniedWithoutRemote()=runBlocking{val remote=Remote();val repo=ProductionFinanceRepository(remote);assertTrue(repo.load(OWNER.copy(role=UserRole.SALESMAN))is FinanceResult.Failure);assertEquals(0,remote.loads)};@Test fun ownerLoadsAndPostsAuthoritativeTransfer()=runBlocking{val remote=Remote();val repo=ProductionFinanceRepository(remote);assertEquals(LEDGER,(repo.load(OWNER)as FinanceResult.Success).value);assertEquals(TRANSFERED,(repo.postTransfer(OWNER,REQUEST,TRANSFER)as FinanceResult.Success).value)};@Test fun invalidSameAccountNeverCallsRpc()=runBlocking{val remote=Remote();val repo=ProductionFinanceRepository(remote);assertTrue(repo.postTransfer(OWNER,REQUEST,TRANSFER.copy(toAccountId=CASH))is FinanceResult.Failure);assertEquals(0,remote.transfers)}
private class Remote:FinanceRemoteDataSource{var loads=0;var transfers=0;override suspend fun load(owner:CacheOwner):RemoteResult<FinanceLedger>{loads++;return RemoteResult.Success(LEDGER)};override suspend fun expense(owner:CacheOwner,id:String,draft:ExpenseDraft)=RemoteResult.Success(PostedExpense(EVENT,EVENT,100,900));override suspend fun movement(owner:CacheOwner,id:String,draft:CashMovementDraft)=RemoteResult.Success(PostedCashMovement("deposit",EVENT,100,1100));override suspend fun transfer(owner:CacheOwner,id:String,draft:TransferDraft):RemoteResult<PostedTransfer>{transfers++;return RemoteResult.Success(TRANSFERED)};override suspend fun reverse(owner:CacheOwner,id:String,draft:FinancialReversalDraft)=RemoteResult.Success(PostedFinancialReversal(EVENT,REQUEST,"transfer"))}
companion object{const val SHOP="11111111-1111-4111-8111-111111111111";const val ACTOR="22222222-2222-4222-8222-222222222222";const val CASH="33333333-3333-4333-8333-333333333333";const val BANK="44444444-4444-4444-8444-444444444444";const val EVENT="55555555-5555-4555-8555-555555555555";const val REQUEST="66666666-6666-4666-8666-666666666666";val OWNER=UserSession(ACTOR,"Owner",UserRole.OWNER,SHOP);val LEDGER=FinanceLedger(listOf(FinanceAccount(CASH,"Cash","cash",1000,true),FinanceAccount(BANK,"Bank","bank",2000,true)));val TRANSFER=TransferDraft(CASH,BANK,500,"2026-07-29","bank deposit");val TRANSFERED=PostedTransfer(EVENT,500,500,2500)}}
